head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[linkedDataList > M > setCondition]<br/>LinkedDataList 모듈의 필터 조건('Filter Condition') 또는 정렬 조건('Sort Condition')을 재설정합니다.",
    "validation" : [
        "type(필수) 파라미터로 설정할 조건(Condition)의 종류를 'sort' 로 설정합니다.",
        "type(필수) 파라미터로 filter 설정 시 LinkedDataList 모듈의 정렬 조건('Sort Condition')을 재설정합니다.",
        "type(필수) 파라미터값은 대소문자를 구분하지 않습니다.",
        "condition(필수) 파라미터로 조건(Condition)값을 문자열로 설정합니다.",        
        "정렬 조건('Sort condition')인 경우 ASC(), DESC() API 와 '&amp;&amp;' 논리 연산자 한 개를 사용할 수 있습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
	// 기존 target 있으면 삭제
    if (typeof gdl_org !== 'undefined') {
        $p.data.remove("gdl_org");
    }

    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }   

    if (typeof gridView2 !== 'undefined') {
        gridView2.remove();
    }     

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

	// target 생성
    $c.gcm.createOrginalDataList();

    let strTarget = '';        
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:linkedDataList ' + strNameSpace + ' id="target1" bind="gdl_org">'
    strTarget += '<w2:condition type="filter"><![CDATA[cat1==ref("data:gdl_org.cat1")]]></w2:condition>'
    strTarget += '<w2:condition type="sort"><![CDATA[]]></w2:condition>'
    strTarget += '</w2:linkedDataList>'

    $p.data.create(strTarget);

    // gridView 생성
    $c.gcm.createOriginalGridView();
    $c.gcm.createLinkedGridView();
} 



scwin.btn_getAllFilteredJSON_onclick = function (e) {
    let rtn = target1.getAllFilteredJSON();
    let jsonString = JSON.stringify(rtn);

	wf_body_bottom.getObj("scwin").setReturnValue("result.json: " + jsonString);
};



scwin.btn_setCondition_onclick = function (e) {
	let type = par_type.getText();
    let condition = par_condition.getText();

    target1.setCondition(type, condition);    

    scwin.btn_getAllFilteredJSON_onclick();
};
